// Writes <name>.module.css.d.ts beside every CSS module, listing the classes
// it exports, so a class missing from its CSS fails the typecheck. Each member
// maps back to its class in the CSS, for go-to-definition. Also fails on a
// `composes:` of a class or file that doesn't exist.
//
// Usage, from packages/client: node scripts/css-module-types.mjs
// Also used by the dev server (vite.config.ts), which keeps them current.
import { existsSync, globSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { basename, dirname, resolve } from "node:path"
import { pathToFileURL } from "node:url"
import { transform } from "lightningcss"
import { composesErrors } from "./css-module-check.mjs"
import { classPositions } from "./css-module-source.mjs"

const SOURCE = "src/**/*.module.css"
const IDENTIFIER = /^[A-Za-z_$][\w$]*$/
const BASE64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
const MEMBER_COLUMN = "  readonly ".length
const HEADER = ["// Generated by scripts/css-module-types.mjs.", "declare const styles: {"]

function vlq(value) {
  let rest = value < 0 ? (-value << 1) | 1 : value << 1
  let out = ""
  do {
    const digit = rest & 31
    rest >>>= 5
    out += BASE64[rest ? digit | 32 : digit]
  } while (rest)
  return out
}

/** Maps each member's name to its class's first selector in the CSS. */
function sourceMap(file, names, positions) {
  let line = 0
  let column = 0
  const members = names.map((name) => {
    const target = positions.get(name)
    if (!target) return ""
    const segment = [MEMBER_COLUMN, 0, target.line - line, target.column - column].map(vlq).join("")
    ;({ line, column } = target)
    return segment
  })
  const mappings = [...HEADER.map(() => ""), ...members].join(";")
  return { version: 3, file: `${basename(file)}.d.ts`, sources: [basename(file)], names: [], mappings }
}

function exportsOf(filename, css) {
  const { exports } = transform({ filename, code: Buffer.from(css), cssModules: true, drafts: { customMedia: true } })
  return exports ?? {}
}

function declarationFor(file, css, exports) {
  const names = Object.keys(exports).sort()
  const members = names.map((name) => `  readonly ${IDENTIFIER.test(name) ? name : JSON.stringify(name)}: string`)
  const map = Buffer.from(JSON.stringify(sourceMap(file, names, classPositions(css)))).toString("base64")
  const body = [...HEADER, ...members, "}", "export default styles"].join("\n")
  return `${body}\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,${map}\n`
}

/** Writes one module's declaration, unless it is already current. Returns the module's composes errors. */
export function writeDeclaration(file) {
  const css = readFileSync(file, "utf8")
  const exports = exportsOf(file, css)
  const target = `${file}.d.ts`
  const text = declarationFor(file, css, exports)
  if (!existsSync(target) || readFileSync(target, "utf8") !== text) writeFileSync(target, text)
  const lookup = (specifier) => {
    const other = resolve(dirname(file), specifier)
    return existsSync(other) ? Object.keys(exportsOf(other, readFileSync(other, "utf8"))) : undefined
  }
  return composesErrors({ file, css, exports, lookup })
}

/** Writes every declaration, drops stale ones, and returns all composes errors. */
export function generateAll() {
  const modules = new Set(globSync(SOURCE))
  const errors = [...modules].flatMap(writeDeclaration)
  for (const declaration of globSync(`${SOURCE}.d.ts`)) {
    if (!modules.has(declaration.slice(0, -".d.ts".length))) rmSync(declaration)
  }
  return errors
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const errors = generateAll()
  if (errors.length) {
    console.error(errors.join("\n"))
    process.exit(1)
  }
}
